package com.vocal.controller;
import com.vocal.dto.CommerceDtos.*; import com.vocal.service.CheckoutService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.security.Principal;
@RestController @RequestMapping("/api/checkout") @RequiredArgsConstructor public class CheckoutController { private final CheckoutService service; @PostMapping OrderResponse checkout(@Valid @RequestBody CheckoutRequest req, Principal p){return service.checkout(req,p);} @PostMapping("/payments/stripe") PaymentIntentResponse stripe(){return new PaymentIntentResponse("stripe","","client_secret_from_stripe");} @PostMapping("/payments/razorpay") PaymentIntentResponse razorpay(){return new PaymentIntentResponse("razorpay","razorpay_order_id","");} }
